fn has_common_element(a: &[i32], b: &[i32]) -> bool {
    // If either slice is empty, no common element can exist
    if a.is_empty() || b.is_empty() {
        return false;
    }

    // For efficiency, check which slice is smaller to build a hash set from
    // so membership checks are O(1) on average instead of O(n*m).
    use std::collections::HashSet;

    if a.len() <= b.len() {
        let set: HashSet<i32> = a.iter().copied().collect();
        b.iter().any(|&elem| set.contains(&elem))
    } else {
        let set: HashSet<i32> = b.iter().copied().collect();
        a.iter().any(|&elem| set.contains(&elem))
    }
}

fn slice_contains(s: &[i32], val: i32) -> bool {
    // Returns true if val is found anywhere in s, false otherwise
    s.iter().any(|&elem| elem == val)
}